"use client"

/**
 * Clean-room new-company dialog. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, or assets were copied.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import {
  companyDraftIssues,
  CRM_LOGO_MAX_BYTES,
  CRM_LOGO_TYPES,
  crmInitials,
  EMPTY_COMPANY_DRAFT,
  type CrmCompanyDraft,
  type CrmDraftIssue,
} from "@/lib/crm-companies"

export type CrmCompanyOption = {
  value: string
  label: string
}

export type CrmNewCompanyLabels = {
  title?: string
  description?: string
  identity?: string
  relationship?: string
  commercial?: string
  logo?: string
  upload?: string
  removeLogo?: string
  name?: string
  email?: string
  website?: string
  status?: string
  statusPlaceholder?: string
  owner?: string
  ownerPlaceholder?: string
  industry?: string
  region?: string
  pipeline?: string
  notes?: string
  cancel?: string
  save?: string
  invalid?: string
  issues?: Partial<Record<CrmDraftIssue, string>>
}

export type CrmNewCompanyDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  statuses: readonly CrmCompanyOption[]
  owners: readonly CrmCompanyOption[]
  onSubmit: (draft: CrmCompanyDraft & { logoUrl?: string }) => void
  labels?: CrmNewCompanyLabels
  className?: string
}

const ISSUE_TEXT: Record<CrmDraftIssue, string> = {
  "name-required": "Enter a name",
  "status-required": "Choose a status",
  "owner-required": "Choose an owner",
  "email-invalid": "Enter a valid email",
  "website-invalid": "Website must start with http:// or https://",
  "pipeline-invalid": "Enter a pipeline value of zero or more",
  "logo-type": "Logo must be a PNG, JPEG, WebP, or GIF",
  "logo-size": "Logo must be 2 MB or smaller",
}

function message(code: CrmDraftIssue, labels?: CrmNewCompanyLabels) {
  return labels?.issues?.[code] ?? ISSUE_TEXT[code]
}

export function CrmNewCompanyDialog({
  open,
  onOpenChange,
  statuses,
  owners,
  onSubmit,
  labels,
  className,
}: CrmNewCompanyDialogProps) {
  const base = React.useId()
  const fileRef = React.useRef<HTMLInputElement>(null)
  const [draft, setDraft] = React.useState<CrmCompanyDraft>(EMPTY_COMPANY_DRAFT)
  const [logoUrl, setLogoUrl] = React.useState<string>()
  const [issues, setIssues] = React.useState<CrmDraftIssue[]>([])
  const wasOpen = React.useRef(false)

  const copy = {
    title: labels?.title ?? "New company",
    description: labels?.description ?? "Add a company to the book. Required fields are marked.",
    identity: labels?.identity ?? "Identity",
    relationship: labels?.relationship ?? "Relationship",
    commercial: labels?.commercial ?? "Commercial",
    logo: labels?.logo ?? "Logo",
    upload: labels?.upload ?? "Upload logo",
    removeLogo: labels?.removeLogo ?? "Remove logo",
    name: labels?.name ?? "Name",
    email: labels?.email ?? "Email",
    website: labels?.website ?? "Website",
    status: labels?.status ?? "Status",
    statusPlaceholder: labels?.statusPlaceholder ?? "Choose a status",
    owner: labels?.owner ?? "Owner",
    ownerPlaceholder: labels?.ownerPlaceholder ?? "Choose an owner",
    industry: labels?.industry ?? "Industry",
    region: labels?.region ?? "Region",
    pipeline: labels?.pipeline ?? "Pipeline value",
    notes: labels?.notes ?? "Notes",
    cancel: labels?.cancel ?? "Cancel",
    save: labels?.save ?? "Save company",
    invalid: labels?.invalid ?? "Fix the highlighted fields",
  }

  React.useEffect(() => {
    if (open && !wasOpen.current) {
      setDraft(EMPTY_COMPANY_DRAFT)
      setLogoUrl(undefined)
      setIssues([])
    }
    wasOpen.current = open
  }, [open])

  function patch(partial: Partial<CrmCompanyDraft>) {
    setDraft((current) => ({ ...current, ...partial }))
  }

  function onFile(file: File | undefined) {
    if (!file) return
    const logo = { type: file.type, size: file.size }
    patch({ logo })
    if (!CRM_LOGO_TYPES.includes(file.type as (typeof CRM_LOGO_TYPES)[number]) || file.size > CRM_LOGO_MAX_BYTES) {
      setLogoUrl(undefined)
      return
    }
    const reader = new FileReader()
    reader.onload = () => {
      setLogoUrl(typeof reader.result === "string" ? reader.result : undefined)
    }
    reader.readAsDataURL(file)
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const next = companyDraftIssues(draft)
    setIssues(next)
    if (next.length > 0) {
      const field: Record<CrmDraftIssue, string> = {
        "name-required": `${base}-name`,
        "status-required": `${base}-status`,
        "owner-required": `${base}-owner`,
        "email-invalid": `${base}-email`,
        "website-invalid": `${base}-website`,
        "pipeline-invalid": `${base}-pipeline`,
        "logo-type": `${base}-logo`,
        "logo-size": `${base}-logo`,
      }
      document.getElementById(field[next[0]])?.focus()
      return
    }
    onSubmit({ ...draft, logoUrl })
    onOpenChange(false)
  }

  function errorFor(codes: CrmDraftIssue[]) {
    const code = codes.find((item) => issues.includes(item))
    if (!code) return null
    return message(code, labels)
  }

  const logoError = errorFor(["logo-type", "logo-size"])
  const nameError = errorFor(["name-required"])
  const emailError = errorFor(["email-invalid"])
  const websiteError = errorFor(["website-invalid"])
  const statusError = errorFor(["status-required"])
  const ownerError = errorFor(["owner-required"])
  const pipelineError = errorFor(["pipeline-invalid"])

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className={cn("max-h-[min(40rem,calc(100dvh-2rem))] overflow-y-auto sm:max-w-lg", className)}>
        <DialogHeader>
          <DialogTitle>{copy.title}</DialogTitle>
          <DialogDescription>{copy.description}</DialogDescription>
        </DialogHeader>
        <form className="flex flex-col gap-5" onSubmit={submit} noValidate>
          {issues.length > 0 ? (
            <p role="alert" className="text-sm text-destructive">
              {copy.invalid}
            </p>
          ) : null}
          <fieldset className="flex flex-col gap-3">
            <legend className="text-sm font-medium">{copy.identity}</legend>
            <div className="flex flex-wrap items-center gap-3">
              <Avatar size="lg">
                {logoUrl ? <AvatarImage src={logoUrl} alt="" /> : null}
                <AvatarFallback>{crmInitials(draft.name || "?")}</AvatarFallback>
              </Avatar>
              <div className="flex min-w-0 flex-col gap-1">
                <Label htmlFor={`${base}-logo`}>{copy.logo}</Label>
                <div className="flex flex-wrap gap-2">
                  <Button type="button" variant="outline" onClick={() => fileRef.current?.click()}>
                    {copy.upload}
                  </Button>
                  {logoUrl ? (
                    <Button
                      type="button"
                      variant="ghost"
                      onClick={() => {
                        setLogoUrl(undefined)
                        patch({ logo: null })
                        if (fileRef.current) fileRef.current.value = ""
                      }}
                    >
                      {copy.removeLogo}
                    </Button>
                  ) : null}
                </div>
                <input
                  ref={fileRef}
                  id={`${base}-logo`}
                  className="sr-only"
                  type="file"
                  accept={CRM_LOGO_TYPES.join(",")}
                  aria-label={copy.upload}
                  aria-invalid={logoError ? true : undefined}
                  aria-describedby={logoError ? `${base}-logo-error` : undefined}
                  onChange={(event) => onFile(event.target.files?.[0])}
                />
                {logoError ? (
                  <p id={`${base}-logo-error`} className="text-xs text-destructive">
                    {logoError}
                  </p>
                ) : null}
              </div>
            </div>
            <Field
              id={`${base}-name`}
              label={copy.name}
              required
              value={draft.name}
              error={nameError}
              onChange={(name) => patch({ name })}
            />
            <Field
              id={`${base}-email`}
              label={copy.email}
              type="email"
              value={draft.email}
              error={emailError}
              onChange={(email) => patch({ email })}
            />
            <Field
              id={`${base}-website`}
              label={copy.website}
              value={draft.website}
              error={websiteError}
              onChange={(website) => patch({ website })}
            />
          </fieldset>
          <fieldset className="flex flex-col gap-3">
            <legend className="text-sm font-medium">{copy.relationship}</legend>
            <Choice
              id={`${base}-status`}
              label={copy.status}
              placeholder={copy.statusPlaceholder}
              value={draft.status}
              options={statuses}
              error={statusError}
              onChange={(status) => patch({ status })}
            />
            <Choice
              id={`${base}-owner`}
              label={copy.owner}
              placeholder={copy.ownerPlaceholder}
              value={draft.ownerId}
              options={owners}
              error={ownerError}
              onChange={(ownerId) => patch({ ownerId })}
            />
            <Field id={`${base}-industry`} label={copy.industry} value={draft.industry} onChange={(industry) => patch({ industry })} />
            <Field id={`${base}-region`} label={copy.region} value={draft.region} onChange={(region) => patch({ region })} />
          </fieldset>
          <fieldset className="flex flex-col gap-3">
            <legend className="text-sm font-medium">{copy.commercial}</legend>
            <Field
              id={`${base}-pipeline`}
              label={copy.pipeline}
              required
              inputMode="decimal"
              value={draft.pipelineValue}
              error={pipelineError}
              onChange={(pipelineValue) => patch({ pipelineValue })}
            />
            <div className="flex flex-col gap-1.5">
              <Label htmlFor={`${base}-notes`}>{copy.notes}</Label>
              <Textarea id={`${base}-notes`} value={draft.notes} onChange={(event) => patch({ notes: event.target.value })} />
            </div>
          </fieldset>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              {copy.cancel}
            </Button>
            <Button type="submit">{copy.save}</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

function Field({
  id,
  label,
  value,
  onChange,
  error,
  required,
  type = "text",
  inputMode,
}: {
  id: string
  label: string
  value: string
  onChange: (value: string) => void
  error?: string | null
  required?: boolean
  type?: string
  inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"]
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label htmlFor={id}>
        {label}
        {required ? <span aria-hidden="true"> *</span> : null}
      </Label>
      <Input
        id={id}
        type={type}
        inputMode={inputMode}
        value={value}
        required={required}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-error` : undefined}
        onChange={(event) => onChange(event.target.value)}
      />
      {error ? (
        <p id={`${id}-error`} className="text-xs text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

function Choice({
  id,
  label,
  placeholder,
  value,
  options,
  error,
  onChange,
}: {
  id: string
  label: string
  placeholder: string
  value: string
  options: readonly CrmCompanyOption[]
  error?: string | null
  onChange: (value: string) => void
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label htmlFor={id}>
        {label}
        <span aria-hidden="true"> *</span>
      </Label>
      <Select value={value || undefined} onValueChange={onChange}>
        <SelectTrigger id={id} aria-invalid={error ? true : undefined} aria-describedby={error ? `${id}-error` : undefined}>
          <SelectValue placeholder={placeholder} />
        </SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {options.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
      {error ? (
        <p id={`${id}-error`} className="text-xs text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

/**
 * Clean-room sales CRM model. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, sample rows, or assets were copied.
 */

export type CrmStatusTone = "neutral" | "emphasis" | "muted" | "danger"

export type CrmCompany = {
  id: string
  name: string
  logoUrl?: string
  status: string
  statusLabel: string
  statusTone?: CrmStatusTone
  owner: string
  ownerId?: string
  pipelineValue: number
  /** 0–100. */
  score: number
  /** Oldest to newest. The table draws this as a sparkline. */
  activity: readonly number[]
  activityLabel: string
  industry?: string
  region?: string
  email?: string
  website?: string
  phone?: string
  notes?: string
  /** Oldest to newest. The detail panel draws this as a trend. */
  trend?: readonly { key: string; label: string; value: number }[]
  /** 0–100 health for the meter. Falls back to score. */
  health?: number
}

export type CrmNotice = {
  id: string
  title: string
  description?: string
  time: string
  dateTime?: string
  read?: boolean
  companyId?: string
}

export type CrmSortKey = "name" | "status" | "owner" | "pipeline" | "score" | "activity"

export type CrmSort = {
  key: CrmSortKey
  direction: "asc" | "desc"
}

export type CrmFacetSelection = Record<string, readonly string[]>

export type CrmCompanyQuery = {
  search?: string
  /** Status id, or the all-segment id. */
  segment?: string
  allSegment?: string
  facets?: CrmFacetSelection
}

export type CrmCsvLabels = {
  name: string
  status: string
  owner: string
  pipeline: string
  score: string
  activity: string
}

export type CrmCompanyDraft = {
  name: string
  status: string
  ownerId: string
  email: string
  website: string
  industry: string
  region: string
  pipelineValue: string
  notes: string
  logo?: { type: string; size: number } | null
}

export type CrmDraftIssue =
  | "name-required"
  | "status-required"
  | "owner-required"
  | "email-invalid"
  | "website-invalid"
  | "pipeline-invalid"
  | "logo-type"
  | "logo-size"

export const CRM_LOGO_TYPES = ["image/png", "image/jpeg", "image/webp", "image/gif"] as const
export const CRM_LOGO_MAX_BYTES = 2_000_000

export const EMPTY_COMPANY_DRAFT: CrmCompanyDraft = {
  name: "",
  status: "",
  ownerId: "",
  email: "",
  website: "",
  industry: "",
  region: "",
  pipelineValue: "",
  notes: "",
  logo: null,
}

export function crmInitials(name: string) {
  const parts = name.split(/\s+/).filter(Boolean).slice(0, 2)
  const letters = parts.map((part) => [...part][0] ?? "").join("")
  return letters.toLocaleUpperCase() || "?"
}

export function companyFacetValue(company: CrmCompany, facetId: string) {
  if (facetId === "owner") return company.ownerId ?? company.owner
  if (facetId === "industry") return company.industry ?? ""
  if (facetId === "region") return company.region ?? ""
  if (facetId === "status") return company.status
  return ""
}

export function companySearchText(company: CrmCompany) {
  return [company.name, company.owner, company.statusLabel, company.industry, company.region, company.email]
    .filter(Boolean)
    .join(" ")
    .toLocaleLowerCase()
}

export function facetSelectionCount(selection: CrmFacetSelection) {
  return Object.values(selection).reduce((sum, values) => sum + values.length, 0)
}

export function toggleFacetValue(selection: CrmFacetSelection, facetId: string, value: string): CrmFacetSelection {
  const current = selection[facetId] ?? []
  const next = current.includes(value) ? current.filter((item) => item !== value) : [...current, value]
  return { ...selection, [facetId]: next }
}

export function filterCompanies(rows: readonly CrmCompany[], query: CrmCompanyQuery = {}) {
  const search = query.search?.trim().toLocaleLowerCase() ?? ""
  const allSegment = query.allSegment ?? "all"
  const segment = query.segment && query.segment !== allSegment ? query.segment : ""
  const facets = Object.entries(query.facets ?? {}).filter(([, values]) => values.length > 0)

  return rows.filter((company) => {
    if (segment && company.status !== segment) return false
    if (search && !companySearchText(company).includes(search)) return false
    return facets.every(([facetId, values]) => values.includes(companyFacetValue(company, facetId)))
  })
}

function sortValue(company: CrmCompany, key: CrmSortKey) {
  switch (key) {
    case "name":
      return company.name
    case "status":
      return company.statusLabel
    case "owner":
      return company.owner
    case "pipeline":
      return company.pipelineValue
    case "score":
      return company.score
    case "activity":
      return company.activity.at(-1) ?? 0
    default: {
      const unreachable: never = key
      return unreachable
    }
  }
}

export function sortCompanies(rows: readonly CrmCompany[], sort: CrmSort) {
  const direction = sort.direction === "asc" ? 1 : -1
  return [...rows].sort((a, b) => {
    const left = sortValue(a, sort.key)
    const right = sortValue(b, sort.key)
    const compared =
      typeof left === "number" && typeof right === "number"
        ? left - right
        : String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: "base" })
    if (compared !== 0) return compared * direction
    return a.id.localeCompare(b.id)
  })
}

export function paginate<T>(rows: readonly T[], page: number, pageSize: number) {
  const size = Math.max(1, Math.floor(pageSize) || 1)
  const total = rows.length
  const pages = Math.max(1, Math.ceil(total / size))
  const index = Math.min(Math.max(0, Math.floor(page) || 0), pages - 1)
  const start = index * size
  return {
    page: index,
    pages,
    start,
    end: Math.min(total, start + size),
    total,
    rows: rows.slice(start, start + size),
  }
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const WEBSITE = /^https?:\/\/\S+$/i

export function companyDraftIssues(draft: CrmCompanyDraft): CrmDraftIssue[] {
  const issues: CrmDraftIssue[] = []
  if (!draft.name.trim()) issues.push("name-required")
  if (!draft.status) issues.push("status-required")
  if (!draft.ownerId) issues.push("owner-required")
  if (draft.email.trim() && !EMAIL.test(draft.email.trim())) issues.push("email-invalid")
  if (draft.website.trim() && !WEBSITE.test(draft.website.trim())) issues.push("website-invalid")
  const pipeline = Number(draft.pipelineValue)
  if (draft.pipelineValue.trim() === "" || !Number.isFinite(pipeline) || pipeline < 0) issues.push("pipeline-invalid")
  if (draft.logo && draft.logo.size > 0) {
    if (!CRM_LOGO_TYPES.includes(draft.logo.type as (typeof CRM_LOGO_TYPES)[number])) issues.push("logo-type")
    if (draft.logo.size > CRM_LOGO_MAX_BYTES) issues.push("logo-size")
  }
  return issues
}

export function companyFromDraft(
  draft: CrmCompanyDraft & { logoUrl?: string },
  context: {
    id: string
    ownerName: string
    statusLabel: string
    statusTone?: CrmStatusTone
    activityLabel: string
  },
): CrmCompany {
  const pipelineValue = Number(draft.pipelineValue)
  return {
    id: context.id,
    name: draft.name.trim(),
    logoUrl: draft.logoUrl,
    status: draft.status,
    statusLabel: context.statusLabel,
    statusTone: context.statusTone,
    owner: context.ownerName,
    ownerId: draft.ownerId,
    pipelineValue: Number.isFinite(pipelineValue) ? pipelineValue : 0,
    score: 50,
    health: 50,
    activity: [2, 2, 3, 3],
    activityLabel: context.activityLabel,
    industry: draft.industry.trim() || undefined,
    region: draft.region.trim() || undefined,
    email: draft.email.trim() || undefined,
    website: draft.website.trim() || undefined,
    notes: draft.notes.trim() || undefined,
    trend: [{ key: "now", label: context.activityLabel, value: 1 }],
  }
}
